import js from '@eslint/js';
import importPlugin from 'eslint-plugin-import';
import globals from 'globals';
import tseslint from 'typescript-eslint';

import architecture from './eslint.architecture.config.js';

export default tseslint.config(
  {
    ignores: [
      '**/dist/**',
      '**/coverage/**',
      '**/node_modules/**',
      // Deliberate dependency-rule violations, asserted by tools/architecture-lint.test.ts.
      'tools/architecture-fixtures/**',
      // Generated by `supabase gen types`; regenerated, never hand-edited.
      '**/database.types.ts',
      'supabase/.branches/**',
      'supabase/.temp/**',
      'playwright-report/**',
      'test-results/**',
    ],
  },

  js.configs.recommended,
  ...tseslint.configs.strictTypeChecked,
  ...tseslint.configs.stylisticTypeChecked,

  {
    languageOptions: {
      globals: { ...globals.node },
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    plugins: { import: importPlugin },
    settings: {
      'import/resolver': {
        typescript: { project: ['packages/*/tsconfig.json', 'apps/*/tsconfig.json'] },
      },
    },
    rules: {
      /* --- TypeScript: see .claude/rules/typescript.md ------------------- */
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-non-null-assertion': 'error',
      '@typescript-eslint/no-floating-promises': 'error',
      '@typescript-eslint/no-misused-promises': 'error',
      '@typescript-eslint/consistent-type-imports': [
        'error',
        { prefer: 'type-imports', fixStyle: 'inline-type-imports' },
      ],
      '@typescript-eslint/switch-exhaustiveness-check': 'error',
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_' },
      ],

      /* --- Style: see .claude/rules/code-style.md ------------------------ */
      'import/order': [
        'error',
        {
          groups: ['builtin', 'external', 'internal', ['parent', 'sibling', 'index']],
          pathGroups: [{ pattern: '@multitenant-base/**', group: 'internal', position: 'before' }],
          pathGroupsExcludedImportTypes: ['builtin'],
          'newlines-between': 'always',
          alphabetize: { order: 'asc', caseInsensitive: true },
        },
      ],
      'import/no-default-export': 'error',
      eqeqeq: ['error', 'always', { null: 'ignore' }],
      'no-else-return': ['error', { allowElseIf: false }],
      'prefer-const': 'error',
      // Mutating a parameter's properties hides side effects — except for the
      // Fastify request/reply pair, where decorating the request *is* the framework's
      // documented mechanism for passing per-request context down the hook chain.
      'no-param-reassign': [
        'error',
        { props: true, ignorePropertyModificationsFor: ['request', 'reply'] },
      ],

      /* --- Observability: see .claude/rules/observability.md -------------
         Structured JSON only (pino). A console.log is an unaggregatable log
         line that also tends to leak data that should never be logged.      */
      'no-console': 'error',
    },
  },

  /* The dependency rule. Also runnable on its own via `pnpm lint:arch`. */
  ...architecture,

  /* Config files live outside every tsconfig project, so type-aware rules cannot
     run on them. They are also the one place a default export is required. */
  {
    files: [
      '*.config.{js,ts}',
      'eslint*.config.js',
      '**/vite.config.ts',
      '**/vitest.config.ts',
      'vitest.workspace.ts',
      'vitest.integration.ts',
    ],
    extends: [tseslint.configs.disableTypeChecked],
    rules: {
      'import/no-default-export': 'off',
    },
  },

  /* The web client runs in a browser, so it needs DOM globals rather than Node's. */
  {
    files: ['apps/web/**/*.{ts,tsx}'],
    languageOptions: { globals: { ...globals.browser } },
  },

  /* Build tooling lives outside every tsconfig project, so type-aware rules
     cannot run on it. */
  {
    files: ['tools/**/*.ts'],
    extends: [tseslint.configs.disableTypeChecked],
  },

  /* Tests may reach for the ergonomics that production code may not. */
  {
    files: ['**/*.test.ts'],
    rules: {
      '@typescript-eslint/no-non-null-assertion': 'off',
      '@typescript-eslint/unbound-method': 'off',
    },
  },
);
